<template>
  <el-header class="me-header">
    <div class="header-container">
      <div class="header-left">
        <router-link to="/" class="me-title">
          <img src="../assets/img/logo.png" alt="卫星地面融合网络社区"/>
        </router-link>
      </div>

      <slot v-if="simple"></slot>

      <nav class="main-nav" v-if="!simple">
        <el-menu 
          :router=true 
          menu-trigger="click" 
          active-text-color="var(--primary-color)" 
          :default-active="activeIndex"
          mode="horizontal">
          <el-menu-item index="/">首页</el-menu-item>
          <el-menu-item index="/category/all">技术分类</el-menu-item>
          <el-menu-item index="/tag/all">技术标签</el-menu-item>
          <el-menu-item index="/archives">技术归档</el-menu-item>
          <el-menu-item index="/resourceDownload">资源下载</el-menu-item>
          <el-menu-item index="/messageBoard">社区留言</el-menu-item>
          <el-menu-item index="/write"><i class="el-icon-edit"></i>写文章</el-menu-item>
          <el-menu-item v-if="isAdmin" index="/admin/dashboard" class="admin-menu-item">
            <i class="el-icon-setting"></i>管理后台
          </el-menu-item>
        </el-menu>
      </nav>

      <div class="header-right">
        <el-menu :router=true menu-trigger="click" mode="horizontal" active-text-color="#5FB878">
          <template v-if="!user.login">
            <el-menu-item index="/login">
              <el-button type="text">登录</el-button>
            </el-menu-item>
            <el-menu-item index="/register">
              <el-button type="text">注册</el-button>
            </el-menu-item>
          </template>
          <template v-else>
            <el-dropdown trigger="click">
              <img class="me-header-picture" :src="user.avatar"/>
              <el-dropdown-menu slot="dropdown">
                <el-dropdown-item>
                  <router-link to="/favorites"><i class="el-icon-star"></i>我的收藏</router-link>
                </el-dropdown-item>
                <el-dropdown-item @click.native="showProfileModal = true">
                  <i class="el-icon-user"></i>个人信息
                </el-dropdown-item>
                <el-dropdown-item divided @click.native="logout">
                  <i class="el-icon-back"></i>退出
                </el-dropdown-item>
              </el-dropdown-menu>
            </el-dropdown>
          </template>
        </el-menu>
        
        <button class="mobile-menu-btn" @click="toggleMobileMenu">
          <i class="el-icon-menu"></i>
        </button>
      </div>
    </div>

    <div class="mobile-menu-overlay" v-if="showMobileMenu" @click="showMobileMenu = false"></div>

    <el-dialog title="个人信息" :visible.sync="showProfileModal" width="400px" @close="resetProfileForm" :modal="false">
      <el-form :model="profileForm" label-width="80px">
        <el-form-item label="头像">
          <div class="avatar-upload">
            <img :src="profileForm.avatar" class="profile-avatar" />
            <el-upload
              class="avatar-uploader"
              action="/upload"
              :show-file-list="false"
              :on-success="handleAvatarSuccess"
              :before-upload="beforeAvatarUpload">
              <i class="el-icon-plus avatar-upload-icon"></i>
            </el-upload>
          </div>
        </el-form-item>
        <el-form-item label="用户名">
          <el-input v-model="profileForm.account" disabled></el-input>
        </el-form-item>
        <el-form-item label="昵称">
          <el-input v-model="profileForm.nickname"></el-input>
        </el-form-item>
        <el-form-item label="邮箱">
          <el-input v-model="profileForm.email"></el-input>
        </el-form-item>
        <el-form-item label="旧密码">
          <el-input v-model="profileForm.oldPassword" type="password" placeholder="不修改密码请留空"></el-input>
        </el-form-item>
        <el-form-item label="新密码">
          <el-input v-model="profileForm.newPassword" type="password" placeholder="不修改密码请留空"></el-input>
        </el-form-item>
        <el-form-item label="确认密码">
          <el-input v-model="profileForm.confirmPassword" type="password" placeholder="不修改密码请留空"></el-input>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="showProfileModal = false">取消</el-button>
        <el-button type="primary" @click="saveProfile">保存</el-button>
      </div>
    </el-dialog>
    
    <div class="mobile-menu" :class="{ 'show': showMobileMenu }">
      <div class="mobile-menu-header">
        <span class="mobile-menu-title">导航菜单</span>
        <button class="mobile-menu-close" @click="showMobileMenu = false">
          <i class="el-icon-close"></i>
        </button>
      </div>
      <ul class="mobile-menu-list">
        <li>
          <router-link to="/" @click="showMobileMenu = false">首页</router-link>
        </li>
        <li>
          <router-link to="/category/all" @click="showMobileMenu = false">技术分类</router-link>
        </li>
        <li>
          <router-link to="/tag/all" @click="showMobileMenu = false">技术标签</router-link>
        </li>
        <li>
          <router-link to="/archives" @click="showMobileMenu = false">技术归档</router-link>
        </li>
        <li>
          <router-link to="/resourceDownload" @click="showMobileMenu = false">资源下载</router-link>
        </li>
        <li>
          <router-link to="/messageBoard" @click="showMobileMenu = false">社区留言</router-link>
        </li>
        <li>
          <router-link to="/write" @click="showMobileMenu = false">
            <i class="el-icon-edit"></i> 写文章
          </router-link>
        </li>
        <li v-if="isAdmin">
          <router-link to="/admin/dashboard" @click="showMobileMenu = false">
            <i class="el-icon-setting"></i> 管理后台
          </router-link>
        </li>
        <li class="mobile-menu-divider"></li>
        <li v-if="!user.login">
          <router-link to="/login" @click="showMobileMenu = false">登录</router-link>
        </li>
        <li v-if="!user.login">
          <router-link to="/register" @click="showMobileMenu = false">注册</router-link>
        </li>
        <li v-else>
          <a href="#" @click="logoutMobile">
            <i class="el-icon-back"></i> 退出
          </a>
        </li>
      </ul>
    </div>
  </el-header>
</template>

<script>
  export default {
    name: 'BaseHeader',
    props: {
      activeIndex: String,
      simple: {
        type: Boolean,
        default: false
      }
    },
    data() {
      return {
        showMobileMenu: false,
        showProfileModal: false,
        profileForm: {
          account: '',
          nickname: '',
          avatar: '',
          email: '',
          oldPassword: '',
          newPassword: '',
          confirmPassword: ''
        }
      }
    },
    computed: {
      user() {
        let login = this.$store.state.account.length != 0
        let avatar = this.$store.state.avatar
        return {
          login, avatar
        }
      },
      isAdmin() {
        return this.$store.state.admin === true
      }
    },
    watch: {
      showProfileModal(val) {
        if (val) {
          this.loadProfile()
        }
      }
    },
    methods: {
      async loadProfile() {
        try {
          const response = await this.$axios.get('/users/profile')
          if (response.code === 0) {
            this.profileForm = response.data
          }
        } catch (error) {
          this.$message.error('获取个人信息失败')
        }
      },
      handleAvatarSuccess(response) {
        if (response.code === 0) {
          this.profileForm.avatar = response.data
          this.$message.success('头像上传成功')
        } else {
          this.$message.error('头像上传失败')
        }
      },
      beforeAvatarUpload(file) {
        const isImage = file.type.indexOf('image') !== -1
        const isLt2M = file.size / 1024 / 1024 < 2

        if (!isImage) {
          this.$message.error('请上传图片格式文件')
        }
        if (!isLt2M) {
          this.$message.error('图片大小不能超过 2MB')
        }
        return isImage && isLt2M
      },
      async saveProfile() {
        if (this.profileForm.newPassword && this.profileForm.newPassword !== this.profileForm.confirmPassword) {
          this.$message.error('两次输入的密码不一致')
          return
        }

        try {
          const profileUpdate = {
            nickname: this.profileForm.nickname,
            avatar: this.profileForm.avatar,
            email: this.profileForm.email
          }
          const response = await this.$axios.post('/users/profile/update', profileUpdate)
          if (response.code === 0) {
            if (this.profileForm.oldPassword && this.profileForm.newPassword) {
              const pwdResponse = await this.$axios.post('/users/password/change', {
                oldPassword: this.profileForm.oldPassword,
                newPassword: this.profileForm.newPassword
              })
              if (pwdResponse.code === 0) {
                this.$message.success('个人信息和密码修改成功')
              } else {
                this.$message.error('个人信息修改成功，但密码修改失败：' + (pwdResponse.msg || '旧密码错误'))
              }
            } else {
              this.$message.success('修改成功')
            }
            this.$store.commit('SET_AVATAR', this.profileForm.avatar)
            this.showProfileModal = false
          } else {
            this.$message.error(response.msg || '修改失败')
          }
        } catch (error) {
          this.$message.error('修改失败')
        }
      },
      resetProfileForm() {
        this.profileForm = {
          account: '',
          nickname: '',
          avatar: '',
          email: '',
          oldPassword: '',
          newPassword: '',
          confirmPassword: ''
        }
      },
      logout() {
        let that = this
        this.$store.dispatch('logout').then(() => {
          this.$router.push({path: '/'})
        }).catch((error) => {
          if (error !== 'error') {
            that.$message({message: error, type: 'error', showClose: true});
          }
        })
      },
      logoutMobile() {
        this.showMobileMenu = false
        this.logout()
      },
      toggleMobileMenu() {
        this.showMobileMenu = !this.showMobileMenu
      }
    }
  }
</script>

<style scoped>
  .me-header {
    position: fixed;
    z-index: 1024;
    min-width: 100%;
    box-shadow: 0 2px 3px hsla(0, 0%, 7%, .1), 0 0 0 1px hsla(0, 0%, 7%, .1);
    background: #fff;
  }

  .header-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
    height: 60px;
  }

  .header-left {
    flex-shrink: 0;
  }

  .me-title {
    display: flex;
    align-items: center;
  }

  .me-title img {
    max-height: 2.4rem;
    max-width: 100%;
  }

  .main-nav {
    flex: 1;
    display: flex;
    justify-content: center;
    margin: 0 20px;
  }

  .main-nav .el-menu {
    border: none;
  }

  .header-right {
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .header-right .el-menu {
    border: none;
  }

  .me-header-picture {
    width: 36px;
    height: 36px;
    border: 1px solid #ddd;
    border-radius: 50%;
    vertical-align: middle;
    background-color: #5fb878;
  }

  .mobile-menu-btn {
    display: none;
    background: none;
    border: none;
    font-size: 24px;
    cursor: pointer;
    padding: 8px;
    color: #333;
  }

  .mobile-menu-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 1023;
  }

  .mobile-menu {
    position: fixed;
    top: 60px;
    left: -280px;
    width: 280px;
    height: calc(100vh - 60px);
    background: #fff;
    z-index: 1025;
    transition: left 0.3s ease;
    box-shadow: 2px 0 12px rgba(0, 0, 0, 0.1);
  }

  .mobile-menu.show {
    left: 0;
  }

  .mobile-menu-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 15px 20px;
    border-bottom: 1px solid #f0f0f0;
    font-size: 16px;
    font-weight: 600;
  }

  .mobile-menu-close {
    background: none;
    border: none;
    font-size: 20px;
    cursor: pointer;
    color: #999;
  }

  .mobile-menu-list {
    list-style: none;
    padding: 0;
    margin: 0;
  }

  .mobile-menu-list li {
    padding: 0;
  }

  .mobile-menu-list li a,
  .mobile-menu-list li router-link {
    display: block;
    padding: 15px 20px;
    color: #333;
    text-decoration: none;
    font-size: 15px;
    border-bottom: 1px solid #f5f5f5;
    transition: background 0.2s;
  }

  .mobile-menu-list li a:hover,
  .mobile-menu-list li router-link:hover {
    background: #f8f9fa;
  }

  .mobile-menu-divider {
    height: 10px;
    background: #f5f5f5;
    border: none;
  }

  @media screen and (max-width: 767px) {
    .header-container {
      padding: 0 15px;
      height: 56px;
    }

    .main-nav {
      display: none;
    }

    .header-right .el-menu {
      display: none;
    }

    .mobile-menu-btn {
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .mobile-menu {
      top: 56px;
      height: calc(100vh - 56px);
    }
  }

  @media screen and (min-width: 768px) and (max-width: 1024px) {
    .header-container {
      padding: 0 20px;
    }

    .main-nav {
      margin: 0 10px;
    }

    .main-nav .el-menu-item {
      padding: 0 10px;
    }
  }

  @media screen and (min-width: 1025px) {
    .header-container {
      max-width: 1200px;
    }
  }

  .admin-menu-item {
    color: #F56C6C !important;
  }

  .admin-menu-item:hover {
    background-color: #fef0f0 !important;
  }

  .profile-avatar {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    border: 2px solid #ddd;
  }

  .avatar-upload {
    position: relative;
    display: inline-block;
  }

  .avatar-uploader {
    position: absolute;
    bottom: -5px;
    right: -5px;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: #5FB878;
    border: 2px solid #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
  }

  .avatar-uploader:hover {
    background: #52c41a;
  }

  .avatar-upload-icon {
    color: #fff;
    font-size: 16px;
  }
</style>


