import Vue from 'vue'
import Router from 'vue-router'
import Home from '@/Home'
/*import Index from '@/views/Index'
import Login from '@/views/Login'
import Register from '@/views/Register'
import Log from '@/views/Log'
import MessageBoard from '@/views/MessageBoard'
import BlogWrite from '@/views/blog/BlogWrite'
import BlogView from '@/views/blog/BlogView'
import BlogAllCategoryTag from '@/views/blog/BlogAllCategoryTag'
import BlogCategoryTag from '@/views/blog/BlogCategoryTag'*/

import {Message} from 'element-ui';


import store from '@/store'

import {getToken} from '@/request/token'

Vue.use(Router)

const router = new Router({
  routes: [
    {
      path: '/write/:id?',
      component: r => require.ensure([], () => r(require('@/views/blog/BlogWrite')), 'blogwrite'),
      meta: {
        requireLogin: true
      },
    },
    {
      path: '/admin',
      component: r => require.ensure([], () => r(require('@/views/admin/AdminLayout')), 'admin'),
      meta: { requireAdmin: true },
      children: [
        {
          path: 'dashboard',
          name: 'Dashboard',
          component: r => require.ensure([], () => r(require('@/views/admin/Dashboard')), 'dashboard')
        },
        {
          path: 'articles',
          name: 'Articles',
          component: r => require.ensure([], () => r(require('@/views/admin/ArticleManagement')), 'articles')
        },
        {
          path: 'comments',
          name: 'Comments',
          component: r => require.ensure([], () => r(require('@/views/admin/CommentManagement')), 'comments')
        },
        {
          path: 'users',
          name: 'Users',
          component: r => require.ensure([], () => r(require('@/views/admin/UserManagement')), 'users')
        },
        {
          path: 'categories',
          name: 'Categories',
          component: r => require.ensure([], () => r(require('@/views/admin/CategoryManagement')), 'categories')
        },
        {
          path: 'tags',
          name: 'Tags',
          component: r => require.ensure([], () => r(require('@/views/admin/TagManagement')), 'tags')
        }
      ]
    },
    {
      path: '',
      component: Home,
      children: [
        {
          path: '/',
          name: 'Home',
          component: r => require.ensure([], () => r(require('@/views/Index')), 'index')
        },
        {
          path: '/log',
          component: r => require.ensure([], () => r(require('@/views/Log')), 'log')
        },
        {
          path: '/archives/:year?/:month?',
          component: r => require.ensure([], () => r(require('@/views/blog/BlogArchive')), 'archives')
        },
        {
          path: '/messageBoard',
          component: r => require.ensure([], () => r(require('@/views/MessageBoard')), 'messageboard')
        },
        {
          path: '/messageboard',
          redirect: '/messageBoard'
        },
        {
          path: '/resourceDownload',
          component: r => require.ensure([], () => r(require('@/views/ResourceDownload')), 'resourcedownload')
        },
        {
          path: '/view/:id',
          component: r => require.ensure([], () => r(require('@/views/blog/BlogView')), 'blogview')
        },
        {
          path: '/category/all',
          component: r => require.ensure([], () => r(require('@/views/blog/BlogAllCategoryTag')), 'blogallcategorytag-category')
        },
        {
          path: '/tag/all',
          component: r => require.ensure([], () => r(require('@/views/blog/BlogAllCategoryTag')), 'blogallcategorytag-tag')
        },
        {
          path: '/category/:id',
          component: r => require.ensure([], () => r(require('@/views/blog/BlogCategoryTag')), 'blogcategorytag-category')
        },
        {
          path: '/tag/:id',
          component: r => require.ensure([], () => r(require('@/views/blog/BlogCategoryTag')), 'blogcategorytag-tag')
        },
        {
          path: '/favorites',
          component: r => require.ensure([], () => r(require('@/views/blog/BlogFavorite')), 'favorites'),
          meta: {
            requireLogin: true
          }
        }
      ]
    },
    {
      path: '/login',
      component: r => require.ensure([], () => r(require('@/views/Login')), 'login')
    },
    {
      path: '/register',
      component: r => require.ensure([], () => r(require('@/views/Register')), 'register')
    }

  ],
  scrollBehavior(to, from, savedPosition) {
    return {x: 0, y: 0}
  }
})

router.beforeEach((to, from, next) => {

  if (getToken()) {

    if (to.path === '/login') {
      next({path: '/'})
    } else {
      if (store.state.account.length === 0) {
        store.dispatch('getUserInfo').then(data => {
          // 获取用户信息后检查管理员权限
          if (to.matched.some(r => r.meta.requireAdmin) && !store.state.admin) {
            Message({
              type: 'warning',
              showClose: true,
              message: '您没有管理员权限'
            })
            next({path: '/'})
          } else {
            next()
          }
        }).catch(() => {
          next({path: '/'})
        })
      } else {
        // 检查管理员权限
        if (to.matched.some(r => r.meta.requireAdmin) && !store.state.admin) {
          Message({
            type: 'warning',
            showClose: true,
            message: '您没有管理员权限'
          })
          next({path: '/'})
        } else {
          next()
        }
      }
    }
  } else {
    if (to.matched.some(r => r.meta.requireLogin) || to.matched.some(r => r.meta.requireAdmin)) {
      Message({
        type: 'warning',
        showClose: true,
        message: '请先登录哦'
      })
      next({path: '/login'})
    }
    else {
      next();
    }
  }
})


export default router



